//! `glowkit-mcp`: a Model Context Protocol server (stdio) that lets AI coding agents search,
//! read and use glowkit components.
//!
//! The component catalog is generated by `scripts/gen-mcp-data.py` and embedded in the binary,
//! so the server needs no network, no repository checkout and no configuration:
//!
//! ```bash
//! cargo install glowkit-mcp
//! claude mcp add glowkit -- glowkit-mcp
//! ```

mod data;
mod guides;
mod render;
mod search;

use rmcp::handler::server::router::prompt::PromptRouter;
use rmcp::handler::server::router::tool::ToolRouter;
use rmcp::handler::server::wrapper::Parameters;
use rmcp::model::{
    Implementation, ListResourcesResult, PaginatedRequestParams, PromptMessage, ReadResourceRequestParams,
    ReadResourceResponse, ReadResourceResult, Resource, ResourceContents, Role, ServerCapabilities, ServerConfig,
};
use rmcp::service::RequestContext;
use rmcp::{
    prompt, prompt_handler, prompt_router, tool, tool_handler, tool_router, ErrorData, RoleServer, ServerHandler,
    ServiceExt,
};
use schemars::JsonSchema;
use serde::Deserialize;

use data::catalog;

#[derive(Debug, Deserialize, JsonSchema)]
pub struct SearchArgs {
    /// Keywords, e.g. "shiny text", "sidebar", "line chart", "chat input", "React Bits Aurora".
    pub query: String,
    /// Optional category name to restrict to (see list_categories), e.g. "Charts" or "Buttons".
    #[serde(default)]
    pub category: Option<String>,
    /// Maximum results (default 10, max 50).
    #[serde(default)]
    pub limit: Option<u32>,
}

#[derive(Debug, Deserialize, JsonSchema)]
pub struct IdArgs {
    /// Component id from search_components (e.g. "shiny-text"); a display name or type name also works.
    pub id: String,
}

#[derive(Debug, Deserialize, JsonSchema)]
pub struct BuildAppArgs {
    /// What the app is for, e.g. "a local LLM chat client with model management".
    pub what: String,
    /// Target platforms (default: "native desktop: Windows, macOS, Linux").
    #[serde(default)]
    pub platform: Option<String>,
}

const RESOURCES: [(&str, &str, &str); 3] = [
    ("glowkit://docs/customizing", "customizing", "Customization guide: theme tokens, component setters, motion and composition."),
    ("glowkit://docs/conventions", "conventions", "Component conventions: builder + egui::Widget, theme-aware colors, animation and state rules."),
    ("glowkit://docs/egui-0.37", "egui-0.37-notes", "egui/eframe 0.37 API changes that coding agents commonly get wrong."),
];

/// The MCP server.
#[derive(Clone)]
pub struct GlowkitServer {
    tool_router: ToolRouter<Self>,
    prompt_router: PromptRouter<Self>,
}

impl Default for GlowkitServer {
    fn default() -> Self {
        Self { tool_router: Self::tool_router(), prompt_router: Self::prompt_router() }
    }
}

fn not_found(id: &str) -> String {
    let cat = catalog();
    let hits = search::search(&cat.components, id, None, 5);
    let mut msg = format!("No component with id \"{id}\".");
    if !hits.is_empty() {
        msg.push_str(" Did you mean: ");
        msg.push_str(&hits.iter().map(|h| format!("`{}`", h.component.id)).collect::<Vec<_>>().join(", "));
        msg.push('?');
    }
    msg.push_str(" Use search_components to find ids.");
    msg
}

#[tool_router]
impl GlowkitServer {
    #[tool(
        description = "Search glowkit's ~700 components, pages and app templates by keywords (ranked over name, id, type, category, the web components each one is equivalent to, and description). Returns ids for get_component.",
        annotations(read_only_hint = true)
    )]
    async fn search_components(&self, Parameters(args): Parameters<SearchArgs>) -> String {
        let cat = catalog();
        let limit = args.limit.unwrap_or(10).clamp(1, 50) as usize;
        let category = args.category.as_deref().map(str::trim).filter(|c| !c.is_empty());
        let hits = search::search(&cat.components, &args.query, category, limit);
        render::search_results(cat, &args.query, category, &hits)
    }

    #[tool(
        description = "Everything needed to use one component: description, category, crate and cargo feature, exact `use` paths (compiler-verified), a usage snippet, its constructors, builder setters, methods and fields, related components and web equivalents.",
        annotations(read_only_hint = true)
    )]
    async fn get_component(&self, Parameters(args): Parameters<IdArgs>) -> Result<String, ErrorData> {
        let cat = catalog();
        match cat.component(&args.id) {
            Some(c) => Ok(render::component(cat, c)),
            None => Err(ErrorData::invalid_params(not_found(&args.id), None)),
        }
    }

    #[tool(description = "List component categories with counts, cargo features and examples.", annotations(read_only_hint = true))]
    async fn list_categories(&self) -> String {
        render::categories(catalog())
    }

    #[tool(
        description = "Full code for an app template, page, shell or section (ids from search_components with category Templates, \"Dashboards & Shells\" or Blocks): the snippet, Cargo.toml, a complete runnable eframe main.rs embedding it, and how to wire in your state and data. Without a matching id, lists the available templates.",
        annotations(read_only_hint = true)
    )]
    async fn get_template(&self, Parameters(args): Parameters<IdArgs>) -> String {
        let cat = catalog();
        match cat.component(&args.id) {
            Some(c) => render::template(cat, c),
            None => {
                let mut out = format!("{}\n\nAvailable templates:\n", not_found(&args.id));
                for c in cat.components.iter().filter(|c| c.template) {
                    out.push_str(&format!("- `{}` ({}): {}\n", c.id, c.category, c.name));
                }
                out
            }
        }
    }

    #[tool(description = "glowkit's Theme: every design token with its default value, the built-in presets, the Theme API and how to customize colors/radius for a brand.", annotations(read_only_hint = true))]
    async fn get_theme(&self) -> String {
        render::theme(catalog())
    }

    #[tool(description = "Project setup: Cargo.toml dependencies and features, an eframe 0.37 app skeleton (App::ui, panels, theme install), running, WebAssembly and Bevy notes.", annotations(read_only_hint = true))]
    async fn get_setup(&self) -> String {
        guides::SETUP.to_string()
    }

    #[tool(
        description = "egui/eframe 0.37 API changes agents usually get wrong (App::ui not update, egui::Panel::left/top, Id::new deprecated, StrokeKind, CornerRadius, Margin) plus glowkit rules (with_state lock, time on wasm). Read before writing egui code.",
        annotations(read_only_hint = true)
    )]
    async fn egui_037_notes(&self) -> String {
        guides::EGUI_037_NOTES.to_string()
    }
}

#[prompt_router]
impl GlowkitServer {
    #[prompt(name = "build-app", description = "Build a polished native Rust app with glowkit for a given purpose, using the glowkit MCP tools.")]
    async fn build_app(&self, Parameters(args): Parameters<BuildAppArgs>) -> Vec<PromptMessage> {
        let platform = args.platform.unwrap_or_else(|| "native desktop: Windows, macOS, Linux".into());
        vec![PromptMessage::new_text(Role::User, guides::build_app_prompt(&args.what, &platform))]
    }
}

#[tool_handler(router = self.tool_router)]
#[prompt_handler(router = self.prompt_router)]
impl ServerHandler for GlowkitServer {
    fn get_info(&self) -> ServerConfig {
        ServerConfig::new(ServerCapabilities::builder().enable_tools().enable_prompts().enable_resources().build())
            .with_server_info(Implementation::new("glowkit-mcp", env!("CARGO_PKG_VERSION")).with_title("glowkit"))
            .with_instructions(guides::INSTRUCTIONS)
    }

    async fn list_resources(
        &self,
        _request: Option<PaginatedRequestParams>,
        _context: RequestContext<RoleServer>,
    ) -> Result<ListResourcesResult, ErrorData> {
        Ok(ListResourcesResult::with_all_items(
            RESOURCES
                .iter()
                .map(|(uri, name, desc)| Resource::new(*uri, *name).with_description(*desc).with_mime_type("text/markdown"))
                .collect(),
        ))
    }

    async fn read_resource(
        &self,
        request: ReadResourceRequestParams,
        _context: RequestContext<RoleServer>,
    ) -> Result<ReadResourceResponse, ErrorData> {
        let text = match request.uri.as_str() {
            "glowkit://docs/customizing" => data::CUSTOMIZING_MD,
            "glowkit://docs/conventions" => data::CONVENTIONS_MD,
            "glowkit://docs/egui-0.37" => guides::EGUI_037_NOTES,
            other => return Err(ErrorData::resource_not_found(format!("unknown resource {other}"), None)),
        };
        Ok(ReadResourceResult::new(vec![ResourceContents::text(text, request.uri.clone()).with_mime_type("text/markdown")]).into())
    }
}

#[tokio::main(flavor = "current_thread")]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    if let Some(arg) = std::env::args().nth(1) {
        match arg.as_str() {
            "--version" | "-V" => {
                println!("glowkit-mcp {}", env!("CARGO_PKG_VERSION"));
                return Ok(());
            }
            _ => {
                println!(
                    "glowkit-mcp {}: MCP server (stdio) for the glowkit UI library.\n\n\
                     Register it with your agent, e.g.\n  claude mcp add glowkit -- glowkit-mcp\n\n\
                     It speaks JSON-RPC on stdin/stdout and is not meant to be run interactively.",
                    env!("CARGO_PKG_VERSION")
                );
                return Ok(());
            }
        }
    }
    // Parse the catalog up front so a broken build fails loudly at start rather than mid-session.
    let _ = catalog();
    let service = GlowkitServer::default().serve(rmcp::transport::stdio()).await?;
    service.waiting().await?;
    Ok(())
}
